using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;using System.Runtime.InteropServices;
static class SuitePreviewLauncher {
 static readonly Dictionary<string,string> Apps=new Dictionary<string,string>{{"workscape","Jago-Workscape.exe"},{"wobble",@"Wobble\Jago-Wobble.exe"},{"dither",@"Dither\Jago-Dither.exe"},{"repeat",@"Repeat\Jago-Repeat.exe"},{"worldbuilding",@"Worldbuilding\Jago-World.exe"},{"material",@"Material\Jago-Material.exe"},{"music",@"Music-SFX\Jago-Sound.exe"},{"library",@"Library-Production\Jago-Library.exe"},{"companion",@"Companion\Jago-Companion.exe"},{"pulse",@"Pulse\Jago-Pulse.exe"}};
 [DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int mode);
 internal static List<Tuple<string,string>> Plan(string root,string[] args,string installed){string local=Path.Combine(root,Apps["workscape"]);if(File.Exists(local)||args.Contains("workscape"))return new List<Tuple<string,string>>{Tuple.Create(local,"")};if(!String.IsNullOrEmpty(installed)&&File.Exists(installed))return new List<Tuple<string,string>>{Tuple.Create(installed,"")};return args.Where(Apps.ContainsKey).Distinct().Select(id=>Tuple.Create(Path.Combine(root,Apps[id]),"")).ToList();}
 static string InstalledWorkscape(){foreach(string channel in new[]{"Preview","Stable"})try{using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Jago Suite\"+channel+@"\Components\workspace")){string path=key==null?null:key.GetValue("Executable") as string;if(path!=null&&File.Exists(path))return path;}}catch{}return null;}
 static bool FocusExisting(string path){foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(path)))try{if(p.Id==Process.GetCurrentProcess().Id||p.MainWindowHandle==IntPtr.Zero||!String.Equals(Path.GetFullPath(p.MainModule.FileName),Path.GetFullPath(path),StringComparison.OrdinalIgnoreCase))continue;if(IsIconic(p.MainWindowHandle))ShowWindow(p.MainWindowHandle,9);SetForegroundWindow(p.MainWindowHandle);return true;}catch{}return false;}
 [STAThread]static void Main(string[] args){string root=AppDomain.CurrentDomain.BaseDirectory,installed=args.Contains("--isolated-no-registry")?null:InstalledWorkscape();foreach(var entry in Plan(root,args,installed)){if(!File.Exists(entry.Item1)){MessageBox.Show("Could not find "+entry.Item1+". Run setup again to repair the selected app.","Jago Suite Preview");continue;}if(Path.GetFileName(entry.Item1).Equals("Jago-Workscape.exe",StringComparison.OrdinalIgnoreCase)&&FocusExisting(entry.Item1))continue;try{Process.Start(new ProcessStartInfo(entry.Item1,entry.Item2){WorkingDirectory=Path.GetDirectoryName(entry.Item1),UseShellExecute=false});}catch(Exception e){MessageBox.Show("Could not open "+Path.GetFileNameWithoutExtension(entry.Item1)+". "+e.Message,"Jago Suite Preview");}}}
}
